#!/usr/bin/env node
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { ConfigError, loadConfig } from './config.js';
import { stderrLogger } from './log.js';
import { createServer } from './server.js';
import { createContext } from './tools/context.js';
async function main() {
    let config;
    try {
        config = loadConfig();
    }
    catch (error) {
        if (error instanceof ConfigError) {
            process.stderr.write(`${error.message}\n`);
            process.exit(1);
        }
        throw error;
    }
    // Signs in on the first tool call, so a wiki that is briefly down does not stop the client.
    const server = createServer(createContext(config, { log: stderrLogger }));
    await server.connect(new StdioServerTransport());
    process.stderr.write(`burrow: ready on stdio (${config.baseUrl}${config.readOnly ? ', read-only' : ''})\n`);
}
main().catch((error) => {
    process.stderr.write(`burrow: fatal: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exit(1);
});

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js';
import { z } from 'zod';
import { toolsFor } from './tools/index.js';
import { tierOf } from './tools/types.js';
import { VERSION } from './version.js';
/** Only the hints that differ from the MCP defaults (not read-only, destructive, not idempotent, open world). */
const ANNOTATIONS = {
    read: { readOnlyHint: true, openWorldHint: false },
    write: { destructiveHint: false, openWorldHint: false },
    delete: { destructiveHint: true, openWorldHint: false },
};
/**
 * The JSON schema the model reads, without what costs tokens and says nothing:
 * `$schema`, the safe-integer `maximum` zod adds to every `.int()`, and the
 * `propertyNames: {type: string}` of a record (JSON keys are strings anyway).
 */
function inputSchema(shape) {
    const { $schema: _, ...schema } = z.toJSONSchema(z.object(shape), {
        target: 'draft-07',
        io: 'input',
        override: ({ jsonSchema }) => {
            if (jsonSchema.maximum === Number.MAX_SAFE_INTEGER)
                delete jsonSchema.maximum;
            const names = jsonSchema.propertyNames;
            if (typeof names === 'object' && names.type === 'string' && Object.keys(names).length === 1)
                delete jsonSchema.propertyNames;
        },
    });
    return schema;
}
export function createServer(ctx, tools = toolsFor(ctx.config.readOnly)) {
    const server = new McpServer({ name: 'burrow', version: VERSION });
    const listed = [];
    for (const tool of tools) {
        const tier = tierOf(tool.name);
        if (!tier)
            throw new Error(`Tool "${tool.name}" has no tier prefix (read_/write_/delete_)`);
        if (listed.some((t) => t.name === tool.name))
            throw new Error(`Tool "${tool.name}" is registered twice`);
        // The SDK validates arguments against `input` and calls the handler.
        server.registerTool(tool.name, { description: tool.description, inputSchema: tool.input }, async (args) => tool.handler(args, ctx));
        listed.push({ name: tool.name, description: tool.description, inputSchema: inputSchema(tool.input), annotations: ANNOTATIONS[tier] });
    }
    // The SDK's own list adds `$schema`, `execution` and default-valued hints to every tool;
    // this one is built once and says the same in fewer tokens.
    server.server.setRequestHandler(ListToolsRequestSchema, () => ({ tools: listed }));
    return server;
}

import { deleteTools } from './delete.js';
import { readTools } from './read.js';
import { writeTools } from './write.js';
/** The tools to register: only `read_` ones when `readOnly`. */
export function toolsFor(readOnly) {
    return readOnly ? [...readTools] : [...readTools, ...writeTools, ...deleteTools];
}
